using System.Security.Cryptography;using System.Text;using System.Text.Json;namespace Challenge;public sealed class WebhookStore{public HashSet<string> Seen=new();public List<string> Effects=new();}public sealed class Receiver(byte[] secret,WebhookStore store){public bool Handle(byte[] raw,string signature){using var doc=JsonDocument.Parse(raw);var normalized=JsonSerializer.SerializeToUtf8Bytes(doc.RootElement);var expected=Convert.ToHexString(HMACSHA256.HashData(secret,normalized)).ToLowerInvariant();if(expected!=signature)return false;var id=doc.RootElement.GetProperty("id").GetString()!;store.Seen.Add(id);store.Effects.Add(id);return true;}}
